# Function to get a property by name
def get_prop(rec, name):
    props = rec.parent_id.article_properties_definition
    for prop in props:
        if prop['string'] == name:
            return prop

# Function to GET a property value
def get_prop_value(prop, record_id):
    # if not prop:
    #     return None
    # Use PostgreSQL jsonb operator ->> to extract the property value as text
    env.cr.execute("""
        SELECT article_properties ->> %s
        FROM knowledge_article
        WHERE id = %s
    """, (prop['name'], record_id))
    row = env.cr.fetchone()
    if not row:
        return None
    return row[0]

# Function to SET a property value
def set_prop_value(prop, prop_value, record_id):
    env.cr.execute("""
        UPDATE knowledge_article
        SET article_properties = jsonb_set(article_properties, %s, %s::jsonb, true)
        WHERE id = %s;
    """, ([prop['name']], f'"{prop_value}"', record_id))

# Function to get the name of a property selection value
def get_selection_name(prop, selection_id):
    for id, name in prop['selection']:
        if id == selection_id:
            return name

# Function to get next deadline
def get_next_deadline(deadline, frequency):
    if not deadline:
        deadline = datetime.date.today()

    if deadline > datetime.date.today():
        return deadline

    if frequency == 'Weekly':
        return deadline + datetime.timedelta(weeks=1)
    elif frequency == 'Monthly':
        # Add one month, handling year rollover
        year = deadline.year + (deadline.month // 12)
        month = deadline.month % 12 + 1
        day = min(deadline.day, 28)
        return datetime.date(year, month, day)
    elif frequency == 'Yearly':
        # Handle February 29th on non-leap years
        return deadline.replace(day=min(deadline.day, 28), year=deadline.year + 1)
    else:
        return False

